/* @ds-bundle: {"format":4,"namespace":"REFRACTION","components":[{"name":"ExhibitTitle"},{"name":"InfoStrip"},{"name":"PictureFrame"}]} */
(function(){
 const make=(tag,style,text)=>{const e=document.createElement(tag);e.style.cssText=style;if(text!==undefined)e.textContent=text;return e;};
 function ExhibitTitle(p={}){const e=make('div','display:flex;flex-direction:column;gap:var(--space-s);color:var(--ink)');const zh=make('div','font-family:var(--font-serif);font-weight:500;letter-spacing:.06em',p.chinese||'折光');zh.className=p.compact?'subtitle':'title';const en=make('div','font-family:var(--font-latin);font-size:24px;letter-spacing:.2em',p.english||'REFRACTION');e.append(zh,en);return e;}
 function InfoStrip(p={}){const e=make('div','display:flex;flex-wrap:wrap;gap:var(--space-l);padding-top:var(--space-s);border-top:1px solid var(--hairline);font-family:var(--font-sans);color:var(--ink);');e.className='meta';const a=make('div','display:flex;flex-direction:column;');a.append(make('div','font-weight:600;',p.date||'2026.11.07—12.06'));const hours=make('div','color:var(--muted);',p.hours||'10:00—18:00 · 周一闭馆');hours.className='caption';a.append(hours);const b=make('div','display:flex;flex-direction:column;');b.append(make('div','',p.venue||'折光实验展厅'));const address=make('div','color:var(--muted);',p.address||'虚构路 18 号');address.className='caption';b.append(address);e.append(a,b);return e;}
 function PictureFrame(p={}){const e=make('figure','margin:0;position:relative;overflow:hidden;border-radius:var(--radius-sharp);width:100%;aspect-ratio:'+(p.ratio||'3 / 4')+';background:var(--surface);');const im=document.createElement('img');im.src=p.src||'../../assets/Photography/refraction-light-v5.png';im.alt='纸白上的蓝青、金红折射光场；AI生成艺术示意';im.style.cssText='width:100%;height:100%;display:block;object-fit:cover;object-position:'+(p.position||'50% 50%')+';';e.append(im);return e;}
 window.REFRACTION={ExhibitTitle,InfoStrip,PictureFrame};})();